---@class KRWarnMB
local KRWarnMB = Class('KRWarnMB')

function KRWarnMB:__init()
    self.ImageTrans = nil
end

function KRWarnMB:__delete()
    self.ImageTrans = nil
end

function KRWarnMB:Awake()
    self.ImageTrans = self.controller.transform:Find("ImgContent")
    if self.ImageTrans then
        ---@type Engine.UI.RawImageAlterable
        local imageAlterable = KTool.GetComponent(self.ImageTrans.gameObject, typeof(RawImageAlterable))
        if imageAlterable then
            imageAlterable.IsAutoAlpha = true
            if I18NModule.Lang == LAN_KR then
                if KTool.UNITY_IOS() then
                    imageAlterable:LoadSprite('Arts/warn_kr/warn_kr.png')
                else
                    imageAlterable:LoadSprite('Arts/warn_kr/warn_kr.png')
                end
            elseif I18NModule.Lang == LAN_JP then
                imageAlterable:LoadSprite('Arts/warn_kr/warn_jp.png')
            end
        end
    end
end

function KRWarnMB:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return KRWarnMB